package com.personal.assistant.module.security.controller;import com.personal.assistant.common.response.ApiResponse;import com.personal.assistant.common.security.SecurityContextHelper;import com.personal.assistant.module.security.entity.SecurityAuditLog;import com.personal.assistant.module.security.service.SecurityAuditService;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/security/audit-logs") public class SecurityAuditController{private final SecurityAuditService service;public SecurityAuditController(SecurityAuditService service){this.service=service;}@GetMapping public ApiResponse<List<SecurityAuditLog>>list(@RequestParam(required=false)String operation,@RequestParam(required=false)String result){return ApiResponse.success(service.list(SecurityContextHelper.currentUserId(),operation,result));}}
